import json

DEFAULT_COOKIES = {}
FIELD_COOKIES = 'cookies'
FIELD_RESPONSE = 'response'
RESPONSE_COOKIES_KEY = 'cookies'
REQUEST_COOKIES_KEY = 'cookies'
COOKIE_FORMAT = '{key}={value}'

class CookiesUtil:
    def __init__(self, cookies_file):
        self._cookies_file = cookies_file
        self._cookies = None

    @property
    def cookies(self):
        return self._cookies

    @cookies.setter
    def cookies(self, value):
        self._cookies = value

    def get_cookies(self, response):
        self.cookies = response[RESPONSE_COOKIES_KEY]
        self._save_cookies()

    def _read_cookies_from_file(self):
        try:
            with open(self._cookies_file, 'r') as file:
                return json.load(file)
        except FileNotFoundError:
            return DEFAULT_COOKIES

    def load_cookies(self):
        return self._read_cookies_from_file()

    def _save_cookies_to_file(self, cookies_data):
        try:
            with open(self._cookies_file, 'w') as file:
                json.dump(cookies_data, file)
            return True
        except OSError:
            return False

    def _save_cookies(self):
        return self._save_cookies_to_file(self.cookies)

    def _format_cookies_str(self, cookies_dict):
        return '; '.join([COOKIE_FORMAT.format(key=key, value=value) for key, value in cookies_dict.items()])

    def set_cookies(self, request):
        request[REQUEST_COOKIES_KEY] = self._format_cookies_str(self.cookies)
